# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: sift
def sift(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: fold
def fold(xs, offset=1):
    return [v + offset for v in xs[1:]]

# region: digest
def digest(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: emit
def emit(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(emit(digest(fold(sift(shape(raw))))))

